{
  "tasks": [
    {
      "task_id": "T1",
      "title": "各城市岗位数量分布",
      "business_question": "不同城市的招聘岗位数量分别是多少？",
      "priority": "P0",
      "priority_reason": "核心需求为探索主要分布，城市是招聘数据的关键维度，统计各城市岗位数是回答“分布”最基础且必要的指标。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "job_count"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "sort",
          "params": {
            "field": "job_count",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T2",
      "title": "各学历层次岗位数量分布",
      "business_question": "不同学历要求（如本科、大专等）的招聘岗位数量分布如何？",
      "priority": "P0",
      "priority_reason": "学历是招聘数据的核心属性，分析其分布有助于理解市场对人才层级的需求结构，属于“主要分布”的关键部分。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "job_count_by_edu"
              }
            ],
            "dimensions": [
              "field_0005"
            ]
          }
        }
      ]
    },
    {
      "task_id": "T3",
      "title": "薪资水平整体概况与极值",
      "business_question": "现有数据中岗位的薪资元数值的最小值、最大值和平均值是多少？",
      "priority": "P1",
      "priority_reason": "虽然用户未指定具体统计口径，但提供薪资数值的描述性统计（min/max/avg）能直观反映数据的集中趋势和离散程度，辅助理解“差异”。注意：仅使用真实的数值字段 field_0004，不解析文本区间。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "min",
                "field": "field_0004",
                "alias": "salary_min"
              },
              {
                "function": "max",
                "field": "field_0004",
                "alias": "salary_max"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "salary_avg"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T4",
      "title": "热门岗位名称分布",
      "business_question": "哪些岗位名称出现的频率最高？",
      "priority": "P1",
      "priority_reason": "岗位名称反映了具体的业务需求方向，识别高频岗位有助于了解市场热点，是对“主要分布”的补充视角。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "job_name_count"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "sort",
          "params": {
            "field": "job_name_count",
            "direction": "desc"
          }
        }
      ]
    }
  ]
}
